"""Ejemplo mínimo: decidir si una nota se puede guardar."""

def puede_guardar(titulo: str) -> bool:
    """Un título válido contiene al menos un carácter que no sea espacio."""
    return bool(titulo.strip())


def crear_nota(titulo: str, cuerpo: str = "") -> dict:
    """Crea una nota «v1»: {"titulo": título recortado, "cuerpo": cuerpo tal cual}."""
    if not puede_guardar(titulo) or "\n" in titulo or "\r" in titulo:
        raise ValueError(f"título inválido: {titulo!r}")
    return {"titulo": titulo.strip(), "cuerpo": cuerpo}

import unittest
from notas import crear_nota


class CrearNotas(unittest.TestCase):
    def test_titulo_y_cuerpo(self):
        self.assertEqual(crear_nota("Mi nota", "Hola"), {"titulo": "Mi nota", "cuerpo": "Hola"})

    def test_cuerpo_vacio(self):
        self.assertEqual(crear_nota("Mi nota", ""), {"titulo": "Mi nota", "cuerpo": ""})
        self.assertEqual(crear_nota("Mi nota"), {"titulo": "Mi nota", "cuerpo": ""})

    def test_recorta_titulo_y_conserva_cuerpo(self):
        self.assertEqual(crear_nota("  Mi nota  ", "  Hola  "), {"titulo": "Mi nota", "cuerpo": "  Hola  "})

    def test_rechaza_titulos_invalidos(self):
        for titulo in ["", "   ", "Mi\nnota", "Mi\rnota"]:
            with self.subTest(titulo=titulo), self.assertRaises(ValueError):
                crear_nota(titulo, "Hola")


if __name__ == "__main__":
    unittest.main()

